=== FILE: tb_irq_ctrl.sv ===
// Self-checking testbench for irq_ctrl (interface_spec.md).
// Three DUT copies (N = 8, 3, 32) share one stimulus. A reference model written
// from the specification predicts every register, irq and irq_id. After every
// rising edge each output is compared with the model. Directed scenarios also
// compare against hard-coded values derived from the specification.
// Prints exactly one verdict line: NIRMAAN-SIM <nonce> <n> passed, <m> failed
`timescale 1ns / 1ps
module tb_irq_ctrl;
  localparam int N0 = 8;
  localparam int N1 = 3;
  localparam int N2 = 32;
  localparam int NI = 3;

  logic        clk   = 1'b0;
  logic        rst_n = 1'b0;
  logic [31:0] src   = 32'h0;
  logic        we    = 1'b0;
  logic [1:0]  addr  = 2'd0;
  logic [31:0] wdata = 32'h0;

  wire [31:0] rd0, rd1, rd2;
  wire        irq0, irq1, irq2;
  wire [4:0]  id0, id1, id2;

  irq_ctrl #(.N(N0)) u_n8 (
    .clk(clk), .rst_n(rst_n), .src(src[N0-1:0]), .we(we), .addr(addr),
    .wdata(wdata), .rdata(rd0), .irq(irq0), .irq_id(id0)
  );
  irq_ctrl #(.N(N1)) u_n3 (
    .clk(clk), .rst_n(rst_n), .src(src[N1-1:0]), .we(we), .addr(addr),
    .wdata(wdata), .rdata(rd1), .irq(irq1), .irq_id(id1)
  );
  irq_ctrl #(.N(N2)) u_n32 (
    .clk(clk), .rst_n(rst_n), .src(src), .we(we), .addr(addr),
    .wdata(wdata), .rdata(rd2), .irq(irq2), .irq_id(id2)
  );

  always #20 clk = ~clk;

  // ---------------------------------------------------------------- bookkeeping
  int     npass = 0;
  int     nfail = 0;
  bit     done  = 1'b0;
  bit     nonce_found = 1'b0;
  string  nonce = "";
  integer seed  = 32'h1F2E3D4C;
  logic [31:0] r;

  // ---------------------------------------------------------------- model (from the spec)
  logic [31:0] m_en   [NI];
  logic [31:0] m_mode [NI];
  logic [31:0] m_pend [NI];
  logic [31:0] m_sq   [NI];

  function automatic int nsrc(input int k);
    case (k)
      0:       return N0;
      1:       return N1;
      default: return N2;
    endcase
  endfunction

  function automatic logic [31:0] mask_of(input int n);
    if (n >= 32) return 32'hFFFF_FFFF;
    return (32'h1 << n) - 32'h1;
  endfunction

  function automatic logic [4:0] lowest(input logic [31:0] v);
    logic [4:0] res;
    res = 5'd0;
    for (int i = 31; i >= 0; i--)
      if (v[i]) res = i[4:0];
    return res;
  endfunction

  // IRQ-LEVEL / IRQ-EDGE: mode 1 = rising edge, mode 0 = high level.
  function automatic logic [31:0] f_detect(input logic [31:0] md, input logic [31:0] s,
                                           input logic [31:0] sq);
    return (md & s & ~sq) | (~md & s);
  endfunction

  // IRQ-W1C / IRQ-ACK: bits a write clears.
  function automatic logic [31:0] f_clear(input int n, input logic w, input logic [1:0] a,
                                          input logic [31:0] d);
    logic [31:0] c;
    integer idx;
    c   = 32'h0;
    idx = d[4:0];
    if (w && a == 2'd2) c = d & mask_of(n);
    if (w && a == 2'd3 && idx < n) c = c | (32'h1 << d[4:0]);
    return c;
  endfunction

  always @(posedge clk) begin
    for (int k = 0; k < NI; k++) begin
      if (!rst_n) begin
        m_en[k]   <= 32'h0;
        m_mode[k] <= 32'h0;
        m_pend[k] <= 32'h0;
        m_sq[k]   <= 32'h0;
      end else begin
        m_sq[k]   <= src & mask_of(nsrc(k));
        // IRQ-SET-WINS: a detection at the same edge as a clear keeps the bit.
        m_pend[k] <= (f_detect(m_mode[k], src & mask_of(nsrc(k)), m_sq[k])
                      | (m_pend[k] & ~f_clear(nsrc(k), we, addr, wdata))) & mask_of(nsrc(k));
        if (we && addr == 2'd0) m_en[k]   <= wdata & mask_of(nsrc(k));
        if (we && addr == 2'd1) m_mode[k] <= wdata & mask_of(nsrc(k));
      end
    end
  end

  function automatic logic exp_irq(input int k);
    return |(m_pend[k] & m_en[k]);
  endfunction

  function automatic logic [4:0] exp_id(input int k);
    return lowest(m_pend[k] & m_en[k]);
  endfunction

  function automatic logic [31:0] exp_rd(input int k, input int a);
    case (a)
      0:       return m_en[k];
      1:       return m_mode[k];
      2:       return m_pend[k];
      default: return {exp_irq(k), 26'b0, exp_id(k)};
    endcase
  endfunction

  // ---------------------------------------------------------------- DUT accessors
  function automatic logic [31:0] dut_rd(input int k);
    case (k)
      0:       return rd0;
      1:       return rd1;
      default: return rd2;
    endcase
  endfunction

  function automatic logic dut_irq(input int k);
    case (k)
      0:       return irq0;
      1:       return irq1;
      default: return irq2;
    endcase
  endfunction

  function automatic logic [4:0] dut_id(input int k);
    case (k)
      0:       return id0;
      1:       return id1;
      default: return id2;
    endcase
  endfunction

  // ---------------------------------------------------------------- checking
  task automatic chk(input string what, input logic [31:0] got, input logic [31:0] exp);
    if (got === exp) begin
      npass = npass + 1;
    end else begin
      nfail = nfail + 1;
      if (nfail <= 40)
        $display("FAIL %s: got %h expected %h at %0t", what, got, exp, $time);
    end
  endtask

  // Reads every register of every copy and compares with the model. Uses reads
  // only (IRQ-READ). Runs between edges.
  task automatic check_all(input string tag);
    logic [1:0] save;
    save = addr;
    for (int a = 0; a < 4; a++) begin
      addr = a[1:0];
      #1;
      for (int k = 0; k < NI; k++)
        chk($sformatf("%s: N=%0d rdata addr %0d", tag, nsrc(k), a), dut_rd(k), exp_rd(k, a));
    end
    for (int k = 0; k < NI; k++) begin
      chk($sformatf("%s: N=%0d irq", tag, nsrc(k)), {31'b0, dut_irq(k)}, {31'b0, exp_irq(k)});
      chk($sformatf("%s: N=%0d irq_id", tag, nsrc(k)), {27'b0, dut_id(k)}, {27'b0, exp_id(k)});
    end
    addr = save;
  endtask

  // One rising edge. Inputs are stable at the edge; outputs are checked after it.
  task automatic cycle(input string tag);
    @(posedge clk);
    #1;
    check_all(tag);
  endtask

  task automatic wr(input logic [1:0] a, input logic [31:0] d, input string tag);
    addr  = a;
    wdata = d;
    we    = 1'b1;
    cycle(tag);
    we    = 1'b0;
    wdata = 32'h0;
  endtask

  // Directed compare against a value derived by hand from the specification.
  task automatic expect_reg(input string what, input int k, input logic [1:0] a,
                            input logic [31:0] exp);
    addr = a;
    #1;
    chk($sformatf("directed %s (N=%0d addr %0d)", what, nsrc(k), a), dut_rd(k), exp);
  endtask

  task automatic expect_irq(input string what, input int k, input logic ei,
                            input logic [4:0] eid);
    chk($sformatf("directed %s (N=%0d) irq", what, nsrc(k)), {31'b0, dut_irq(k)}, {31'b0, ei});
    chk($sformatf("directed %s (N=%0d) irq_id", what, nsrc(k)), {27'b0, dut_id(k)}, {27'b0, eid});
  endtask

  task automatic finish_run();
    if (!done) begin
      done = 1'b1;
      $display("NIRMAAN-SIM %s %0d passed, %0d failed", nonce, npass, nfail);
      $finish;
    end
  endtask

  // ---------------------------------------------------------------- watchdog
  initial begin
    #1000000;
    if (!done) begin
      nfail = nfail + 1;
      $display("FAIL watchdog: run did not complete");
      finish_run();
    end
  end

  // ---------------------------------------------------------------- stimulus
  initial begin
    if ($value$plusargs("NIRMAAN_NONCE=%s", nonce)) nonce_found = 1'b1;
    else if ($value$plusargs("nirmaan_nonce=%s", nonce)) nonce_found = 1'b1;
    else if ($value$plusargs("NIRMAAN_SIM_NONCE=%s", nonce)) nonce_found = 1'b1;
    else if ($value$plusargs("NONCE=%s", nonce)) nonce_found = 1'b1;
    else if ($value$plusargs("nonce=%s", nonce)) nonce_found = 1'b1;

    // ---------------- S0: reset (IRQ-RESET). The write and active sources are ignored.
    rst_n = 1'b0; src = 32'hFFFF_FFFF; we = 1'b1; addr = 2'd0; wdata = 32'hFFFF_FFFF;
    cycle("reset");
    cycle("reset");
    expect_reg("reset ENABLE", 0, 2'd0, 32'h0);
    expect_reg("reset MODE", 0, 2'd1, 32'h0);
    expect_reg("reset PENDING", 0, 2'd2, 32'h0);
    expect_reg("reset PENDING", 2, 2'd2, 32'h0);
    expect_irq("reset", 0, 1'b0, 5'd0);
    we = 1'b0; wdata = 32'h0; src = 32'h0; addr = 2'd0; rst_n = 1'b1;
    cycle("post-reset");
    expect_reg("post-reset PENDING", 0, 2'd2, 32'h0);

    // ---------------- S1: register write/read and parameter mask (IRQ-REG-RW, IRQ-PARAM, IRQ-W1C)
    wr(2'd0, 32'hFFFF_FFFF, "enable all");
    expect_reg("ENABLE all ones", 0, 2'd0, 32'h0000_00FF);
    expect_reg("ENABLE all ones", 1, 2'd0, 32'h0000_0007);
    expect_reg("ENABLE all ones", 2, 2'd0, 32'hFFFF_FFFF);
    wr(2'd1, 32'hA5A5_A5A5, "mode pattern");
    expect_reg("MODE A5", 0, 2'd1, 32'h0000_00A5);
    expect_reg("MODE A5", 1, 2'd1, 32'h0000_0005);
    expect_reg("MODE A5", 2, 2'd1, 32'hA5A5_A5A5);
    wr(2'd1, 32'h0, "mode clear");
    expect_reg("MODE zero", 0, 2'd1, 32'h0);
    wr(2'd0, 32'h0, "enable clear");
    expect_reg("ENABLE zero", 0, 2'd0, 32'h0);
    wr(2'd2, 32'hFFFF_FFFF, "w1c never sets");
    expect_reg("PENDING not set by write", 0, 2'd2, 32'h0);
    expect_reg("PENDING not set by write", 2, 2'd2, 32'h0);
    expect_reg("CLAIM idle", 0, 2'd3, 32'h0);
    expect_irq("idle", 0, 1'b0, 5'd0);
    addr = 2'd2; cycle("read only");
    addr = 2'd3; cycle("read only");
    expect_reg("ENABLE after reads", 0, 2'd0, 32'h0);

    // ---------------- S2: level detection, disabled detection, masking, set wins
    src = 32'h4;
    cycle("level detect disabled");
    expect_reg("level detect while disabled", 0, 2'd2, 32'h4);
    expect_reg("level detect while disabled", 1, 2'd2, 32'h4);
    expect_irq("disabled source no irq", 0, 1'b0, 5'd0);
    src = 32'h0;
    cycle("level sticky");
    expect_reg("pending sticky", 0, 2'd2, 32'h4);
    wr(2'd0, 32'h4, "enable src2");
    expect_irq("enable pending src2", 0, 1'b1, 5'd2);
    expect_irq("enable pending src2", 1, 1'b1, 5'd2);
    expect_reg("CLAIM src2", 0, 2'd3, 32'h8000_0002);
    wr(2'd2, 32'h4, "w1c src2");
    expect_reg("w1c clears", 0, 2'd2, 32'h0);
    expect_irq("w1c clears", 0, 1'b0, 5'd0);
    src = 32'h4;
    cycle("level again");
    expect_irq("level again", 0, 1'b1, 5'd2);
    wr(2'd2, 32'h4, "w1c while level high");
    expect_reg("set wins over w1c", 0, 2'd2, 32'h4);
    expect_irq("set wins over w1c", 0, 1'b1, 5'd2);
    wr(2'd3, 32'h2, "ack while level high");
    expect_reg("set wins over ack", 0, 2'd2, 32'h4);
    src = 32'h0;
    wr(2'd3, 32'h2, "ack src2");
    expect_reg("ack clears", 0, 2'd2, 32'h0);
    expect_irq("ack clears", 0, 1'b0, 5'd0);
    src = 32'h6;
    cycle("two level sources");
    src = 32'h0;
    wr(2'd2, 32'h2, "w1c one bit");
    expect_reg("w1c leaves other bits", 0, 2'd2, 32'h4);
    wr(2'd2, 32'h4, "w1c rest");
    expect_reg("w1c rest", 0, 2'd2, 32'h0);

    // ---------------- S3: rising-edge detection (IRQ-EDGE, IRQ-SET-WINS)
    wr(2'd1, 32'h10, "mode src4 edge");
    expect_reg("MODE src4", 0, 2'd1, 32'h10);
    expect_reg("MODE src4 out of range", 1, 2'd1, 32'h0);
    wr(2'd0, 32'h10, "enable src4");
    src = 32'h10;
    cycle("edge rise");
    expect_reg("edge detected", 0, 2'd2, 32'h10);
    expect_irq("edge detected", 0, 1'b1, 5'd4);
    cycle("edge held");
    expect_reg("edge held", 0, 2'd2, 32'h10);
    wr(2'd2, 32'h10, "w1c edge held");
    expect_reg("held edge sets once", 0, 2'd2, 32'h0);
    expect_irq("held edge sets once", 0, 1'b0, 5'd0);
    cycle("edge held after clear");
    expect_reg("edge held after clear", 0, 2'd2, 32'h0);
    src = 32'h0;
    cycle("edge fall");
    expect_reg("edge fall", 0, 2'd2, 32'h0);
    src = 32'h10;
    cycle("edge rise 2");
    expect_reg("second edge", 0, 2'd2, 32'h10);
    src = 32'h0;
    cycle("edge fall 2");
    src = 32'h10;
    wr(2'd3, 32'h4, "ack at new edge");
    expect_reg("edge wins over ack", 0, 2'd2, 32'h10);
    expect_irq("edge wins over ack", 0, 1'b1, 5'd4);
    src = 32'h0;
    wr(2'd3, 32'h4, "ack src4");
    expect_reg("ack src4", 0, 2'd2, 32'h0);

    // ---------------- S4: priority, masking, acknowledge (IRQ-MASK, IRQ-PRIORITY, IRQ-ACK, IRQ-CLAIM)
    wr(2'd1, 32'h0, "mode level");
    wr(2'd0, 32'h0, "enable none");
    src = 32'h68;
    cycle("three sources");
    src = 32'h0;
    cycle("three sources latched");
    expect_reg("pending 3,5,6", 0, 2'd2, 32'h68);
    expect_irq("none enabled", 0, 1'b0, 5'd0);
    wr(2'd0, 32'h60, "enable 5,6");
    expect_irq("lower disabled source skipped", 0, 1'b1, 5'd5);
    wr(2'd0, 32'hFF, "enable all n8");
    expect_irq("lowest wins", 0, 1'b1, 5'd3);
    expect_reg("CLAIM src3", 0, 2'd3, 32'h8000_0003);
    wr(2'd3, 32'h3, "ack 3");
    expect_reg("ack 3", 0, 2'd2, 32'h60);
    expect_irq("ack 3", 0, 1'b1, 5'd5);
    wr(2'd3, 32'h5, "ack 5");
    expect_reg("ack 5", 0, 2'd2, 32'h40);
    expect_irq("ack 5", 0, 1'b1, 5'd6);
    wr(2'd3, 32'h8, "ack out of range n8");
    expect_reg("ack >= N ignored", 0, 2'd2, 32'h40);
    expect_irq("ack >= N ignored", 0, 1'b1, 5'd6);
    wr(2'd3, 32'hFFFF_FFE6, "ack 6 upper bits set");
    expect_reg("ack uses bits 4:0", 0, 2'd2, 32'h0);
    expect_irq("ack uses bits 4:0", 0, 1'b0, 5'd0);
    expect_reg("ack uses bits 4:0", 2, 2'd2, 32'h0);
    src = 32'h81;
    cycle("first and last");
    src = 32'h0;
    cycle("first and last latched");
    expect_irq("src0 highest", 0, 1'b1, 5'd0);
    wr(2'd2, 32'h1, "w1c src0");
    expect_reg("w1c src0", 0, 2'd2, 32'h80);
    expect_irq("last source", 0, 1'b1, 5'd7);
    wr(2'd2, 32'h80, "w1c src7");
    expect_irq("all clear", 0, 1'b0, 5'd0);

    // N=3: acknowledge numbers of N or more
    src = 32'h7;
    cycle("n3 all");
    src = 32'h0;
    cycle("n3 all latched");
    expect_reg("n3 pending", 1, 2'd2, 32'h7);
    expect_irq("n3 pending", 1, 1'b1, 5'd0);
    wr(2'd3, 32'h5, "ack 5");
    expect_reg("n3 ack 5 ignored", 1, 2'd2, 32'h7);
    expect_reg("n8 ack 5 no-op", 0, 2'd2, 32'h7);
    wr(2'd3, 32'h0, "ack 0");
    expect_reg("n3 ack 0", 1, 2'd2, 32'h6);
    wr(2'd3, 32'h3, "ack 3");
    expect_reg("n3 ack 3 ignored", 1, 2'd2, 32'h6);
    expect_irq("n3 ack 3 ignored", 1, 1'b1, 5'd1);
    wr(2'd2, 32'hFFFF_FFFF, "clear all");
    expect_reg("clear all", 1, 2'd2, 32'h0);
    expect_reg("clear all", 0, 2'd2, 32'h0);

    // N=32: source 31
    src = 32'h8000_0000;
    cycle("n32 src31");
    src = 32'h0;
    cycle("n32 src31 latched");
    expect_reg("n32 pending 31", 2, 2'd2, 32'h8000_0000);
    expect_irq("n32 src31 disabled", 2, 1'b0, 5'd0);
    expect_reg("n8 ignores src31", 0, 2'd2, 32'h0);
    wr(2'd0, 32'hFFFF_FFFF, "enable all");
    expect_irq("n32 src31", 2, 1'b1, 5'd31);
    expect_reg("n32 CLAIM 31", 2, 2'd3, 32'h8000_001F);
    wr(2'd3, 32'd31, "ack 31");
    expect_reg("n32 ack 31", 2, 2'd2, 32'h0);
    expect_irq("n32 ack 31", 2, 1'b0, 5'd0);

    // ---------------- S5: reset in the middle of operation
    wr(2'd1, 32'h0F, "mode 0-3 edge");
    src = 32'h0F;
    cycle("edges before reset");
    expect_reg("edges before reset", 0, 2'd2, 32'h0F);
    expect_irq("edges before reset", 0, 1'b1, 5'd0);
    rst_n = 1'b0; we = 1'b1; addr = 2'd0; wdata = 32'hFFFF_FFFF;
    cycle("mid reset");
    expect_reg("mid reset ENABLE", 0, 2'd0, 32'h0);
    expect_reg("mid reset MODE", 0, 2'd1, 32'h0);
    expect_reg("mid reset PENDING", 0, 2'd2, 32'h0);
    expect_reg("mid reset ENABLE", 2, 2'd0, 32'h0);
    expect_irq("mid reset", 0, 1'b0, 5'd0);
    rst_n = 1'b1; we = 1'b0; wdata = 32'h0;
    cycle("release with src high");
    expect_reg("level after reset", 0, 2'd2, 32'h0F);
    expect_irq("disabled after reset", 0, 1'b0, 5'd0);
    src = 32'h0;
    wr(2'd2, 32'hFFFF_FFFF, "clear after reset");
    expect_reg("clear after reset", 0, 2'd2, 32'h0);

    // ---------------- S6: seeded random traffic, checked against the model each edge
    for (int c = 0; c < 600; c++) begin
      r     = $random(seed);
      rst_n = (r[5:0] != 6'd0);
      we    = r[6];
      addr  = r[9:8];
      if (r[10]) src = $random(seed);
      wdata = $random(seed);
      if (addr == 2'd2 && r[11]) wdata = wdata & $random(seed);
      cycle("random");
    end
    rst_n = 1'b1; we = 1'b0; wdata = 32'h0; src = 32'h0;
    cycle("drain");

    if (!nonce_found) begin
      nfail = nonce_found ? nfail : nfail + 1;
      nonce = "UNSET";
      $display("FAIL nonce plusarg not found");
    end
    finish_run();
  end
endmodule
=== END FILE ===
